  "source": "def select_latest(events, keys):
    selected = {}
    for ev in events:
        k = ev["key"]
        t = ev["time"]
        v = ev["value"]
        if k not in selected or t >= selected[k][0]:
            selected[k] = (t, v)
    result = []
    for k in keys:
        val = selected.get(k)[1] if k in selected else None
        result.append({"key": k, "value": val})
    return result

